#!/usr/bin/env bun
// Compiles the avatar rig (reference/avatar-rig) into a typed module the app
// imports. The rig stays the source of truth; this file is generated.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const RIG = "reference/avatar-rig";
const rig = JSON.parse(readFileSync(join(RIG, "rig.json"), "utf8"));

const parts: Record<string, Record<string, string>> = {};
for (const slot of Object.keys(rig.slots)) {
  parts[slot] = {};
  for (const file of readdirSync(join(RIG, "parts", slot))) {
    if (!file.endsWith(".svg")) continue;
    const svg = readFileSync(join(RIG, "parts", slot, file), "utf8");
    const inner = svg
      .replace(/^[\s\S]*?<svg[^>]*>/, "")
      .replace(/<\/svg>[\s\S]*$/, "")
      .trim();
    parts[slot][file.replace(/\.svg$/, "")] = inner;
  }
}

const out = `// GENERATED by tools/build-avatar.ts from reference/avatar-rig — do not edit.
export type RigPart = { layer: string; markup: string };

export const RIG = {
  viewBox: ${JSON.stringify(rig.viewBox)},
  frame: ${JSON.stringify(rig.frame)},
  layers: ${JSON.stringify(rig.layers)} as string[],
  default: ${JSON.stringify(rig.default)} as Record<string, string>,
  palette: ${JSON.stringify(rig.palette)} as Record<string, string>,
  parts: ${JSON.stringify(parts, null, 2)} as Record<string, Record<string, string>>,
};

/** Split a part's markup into its data-layer groups. */
export function partLayers(slot: string, id: string): RigPart[] {
  const markup = RIG.parts[slot]?.[id];
  if (!markup) throw new Error(\`avatar part missing: \${slot}/\${id}\`);
  const out: RigPart[] = [];
  const re = /<g data-layer="([^"]+)">([\\s\\S]*?)<\\/g>/g;
  for (const match of markup.matchAll(re)) out.push({ layer: match[1] ?? '', markup: (match[2] ?? '').trim() });
  return out;
}
`;

writeFileSync("src/lib/avatar-parts.ts", out);
console.log(`avatar-parts.ts written (${Object.values(parts).flatMap(Object.keys).length} parts)`);
